package mclite;
import javax.imageio.ImageIO; import javax.swing.*; import java.awt.*; import java.awt.image.*; import java.io.*;
public class CrashDialogTest { public static void main(String[] a)throws Exception{ SwingUtilities.invokeAndWait(()->{ JFrame owner=new JFrame(); owner.setSize(200,100); owner.setVisible(true); var r=new CrashAnalyzer.Result("Description: Exception in server tick loop", java.util.List.of("examplemod-1.2.jar","sodium-0.5.jar"), "Description: Exception...\njava.lang.NullPointerException\n at com.example.examplemod.Foo.bar(Foo.java:1)\n", java.nio.file.Path.of("/tmp/crash.txt")); var d=new CrashDialog(owner,r,-1); Timer t=new Timer(900,e->{ try{ var img=new BufferedImage(d.getContentPane().getWidth(),d.getContentPane().getHeight(),BufferedImage.TYPE_INT_RGB); var g=img.createGraphics(); d.getContentPane().paint(g); g.dispose(); ImageIO.write(img,"png",new File("build/crash-dialog.png")); }catch(Exception ex){ex.printStackTrace();} d.dispose(); owner.dispose(); System.exit(0); }); t.setRepeats(false); t.start(); d.setVisible(true); }); } }
